// Why Code: parsarea unui update Telegram (mesaj sau buton), whitelist de chat-uri și redactarea PII înainte de agent (LLM în cloud).
const u = $input.first().json ?? {};
const allowed = String($env.TG_BROKER_CHAT_IDS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
const cb = u.callback_query;
const msg = cb ? cb.message : u.message;
const chatId = String(msg?.chat?.id ?? '');
const out = (o) => [{ json: { chatId, callbackId: cb?.id ?? '', claimId: '', question: '', hint: '', ...o } }];

// Doar chat-urile brokerilor (TG_BROKER_CHAT_IDS); restul sunt ignorate fără niciun răspuns.
if (!chatId || !allowed.includes(chatId)) return out({ kind: 'ignore' });

if (cb) {
  const m = /^(take|ask):([0-9a-f-]{36})$/i.exec(String(cb.data ?? ''));
  return m ? out({ kind: m[1].toLowerCase(), claimId: m[2].toLowerCase() }) : out({ kind: 'ignore' });
}

const norm = (s) => String(s ?? '').replace(/ş/g, 'ș').replace(/Ş/g, 'Ș').replace(/ţ/g, 'ț').replace(/Ţ/g, 'Ț').replace(/\s+/g, ' ').trim();
// Structură de CNP (sex, dată validă, județ), ca parseCnp() din lib/verify/ids.ts: un CNP cu cifra de control greșită (typo) tot e PII.
const cnpOk = (d) => {
  if (!/^[1-9]\d{12}$/.test(d)) return false;
  const s = Number(d[0]), yy = Number(d.slice(1, 3)), mm = Number(d.slice(3, 5)), dd = Number(d.slice(5, 7)), county = Number(d.slice(7, 9));
  const nowYY = new Date().getUTCFullYear() % 100;
  const year = s <= 2 ? 1900 + yy : s <= 4 ? 1800 + yy : s <= 6 ? 2000 + yy : (yy <= nowYY ? 2000 : 1900) + yy;
  const probe = new Date(Date.UTC(year, mm - 1, dd));
  if (probe.getUTCFullYear() !== year || probe.getUTCMonth() !== mm - 1 || probe.getUTCDate() !== dd) return false;
  return (county >= 1 && county <= 46) || county === 51 || county === 52 || county === 99;
};
// Aceleași tipare ca lib/verify/redact.ts (testul apps/web/lib/verify/n8n-redact.test.ts rulează exact funcțiile de aici).
const redact = (text) => {
  let out = norm(text);
  out = out.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '<EMAIL>');
  out = out.replace(/(?<![A-Za-z0-9])[A-Z]{2}\d{2}(?:[ ]?[A-Z0-9]{4}){2,7}(?:[ ]?[A-Z0-9]{1,4})?(?![A-Za-z0-9])/g, (m) => (m.replace(/\s/g, '').length >= 15 ? '<IBAN>' : m));
  out = out.replace(/(?<![A-Za-z0-9])[A-Z]{2,5}-(?:RCA|CASCO|PAD|LOC|VIA|ALT)-\d{3,}(?![A-Za-z0-9])/g, '<SERIE_POLITA>');
  out = out.replace(/(?<![A-Za-z0-9])[A-HJ-NPR-Z0-9]{17}(?![A-Za-z0-9])/g, (m) => (/[A-Z]/.test(m) && /\d/.test(m) ? '<VIN>' : m));
  out = out.replace(/(?<!\d)[1-9]\d{12}(?!\d)/g, (m) => (cnpOk(m) ? '<CNP>' : m));
  out = out.replace(/(?<![\d+])(?:(?:\+|00)40[\s.-]?|0)[237](?:[\s.-]?\d){8}(?!\d)/g, '<TELEFON>');
  out = out.replace(/(?<![A-Za-z0-9])(?:B|AB|AR|AG|BC|BH|BN|BT|BR|BV|BZ|CL|CS|CJ|CT|CV|DB|DJ|GL|GR|GJ|HR|HD|IL|IS|IF|MM|MH|MS|NT|OT|PH|SM|SJ|SB|SV|TR|TM|TL|VL|VS|VN)[\s-]?\d{2,3}[\s-]?[A-Z]{3}(?![A-Za-z0-9])/gi, '<NR_INMATRICULARE>');
  return out;
};

const text = String(msg?.text ?? '').trim();
if (!text) return out({ kind: 'help' });
const c = /^\/(\w+)(?:@\w+)?(?:\s+([\s\S]*))?$/.exec(text);
const cmd = c ? c[1].toLowerCase() : '';
if (cmd === 'start' || cmd === 'help' || cmd === 'ajutor') return out({ kind: 'help' });
// comenzile vechi rămân scurtături către agent
const raw = cmd === 'dosare' ? 'Ce dosare deschise sunt?' : cmd === 'intreaba' ? String(c[2] ?? '') : c ? '' : text;
if (!raw.trim()) return out({ kind: 'help', hint: 'Scrie întrebarea după comandă, de exemplu: /intreaba ce acoperă CASCO la furtul de oglinzi?' });
return out({ kind: 'agent', question: redact(raw.slice(0, 600)) });

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Why Code: textul de răspuns în română, în funcție de rezultatul funcției broker_take_claim (mai multe cazuri); niciun nod nativ nu compune textul.
const p = $('Parse update').first().json;
const r = $input.first().json ?? {};
const errors = {
  not_found: '⚠️ Nu găsesc dosarul.',
  taken: `⚠️ Dosarul ${esc(r.ref)} e deja preluat de alt broker.`,
  closed: `ℹ️ Dosarul ${esc(r.ref)} e închis.`,
  not_ready: `ℹ️ Dosarul ${esc(r.ref)} nu e încă trimis de clienți (lipsesc semnăturile sau datele).`,
};
let text;
if (r.error && r.ok === undefined) text = '⚠️ Nu am putut prelua dosarul acum. Încearcă din nou sau deschide-l în dashboard.';
else if (r.ok === false) text = errors[r.error] ?? '⚠️ Nu am putut prelua dosarul.';
else if (r.already) text = `ℹ️ Dosarul <b>${esc(r.ref)}</b> e deja în lucru.`;
else {
  text = `✅ Ai preluat dosarul <b>${esc(r.ref)}</b>. Status: în lucru.`;
  if (r.handoffs > 0) text += `\nConversațiile legate de dosar au trecut la tine; AI-ul nu mai răspunde acolo.`;
  if (!r.assigned) text += `\n(Chatul nu e legat de un broker în baza de date, deci dosarul nu are broker asignat.)`;
}
return [{ json: { chatId: p.chatId, text } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Why Code: lista de lipsuri + un mesaj-draft pentru client, în română.
const p = $('Parse update').first().json;
let rows = [];
try { rows = JSON.parse($input.first().json.data || '[]'); } catch { rows = []; }
const c = Array.isArray(rows) ? rows[0] : null;
if (!c) return [{ json: { chatId: p.chatId, text: '⚠️ Nu găsesc dosarul.', claimId: null, missing: [] } }];

// Fiecare lipsă are un cod din aplicație (lib/claims/completeness.ts), de exemplu photos_B. Codul spune ce îi cerem clientului.
const ASK = {
  party: (r) => `datele șoferului ${r}`,
  docs: (r) => `actele șoferului ${r} (talon, permis, poliță)`,
  circumstances: (r) => `circumstanțele bifate de șoferul ${r}`,
  impact: (r) => `zona lovită a vehiculului ${r}`,
  signature: (r) => `semnătura șoferului ${r}`,
  photos: (r) => `poze cu daunele vehiculului ${r}`,
  sketch: () => 'schița accidentului',
};
const items = (Array.isArray(c.missing_items) ? c.missing_items : []).filter((m) => m?.label);
let text;
if (items.length === 0) {
  text = `✅ La dosarul <b>${esc(c.public_ref)}</b> nu lipsește nimic.`;
} else {
  const list = items.map((m) => `• ${esc(m.label)}`).join('\n');
  const asks = items.map((m) => { const [kind, role] = String(m.code ?? '').split('_'); return ASK[kind]?.(role) ?? m.label; });
  const joined = asks.length > 1 ? `${asks.slice(0, -1).join(', ')} și ${asks[asks.length - 1]}` : asks[0];
  const draft = `Bună ziua! Pentru dosarul ${c.public_ref} mai avem nevoie de: ${joined}. Ne puteți ajuta cu aceste informații? Vă mulțumim!`;
  text = `📋 <b>${esc(c.public_ref)}</b>: lipsesc\n${list}\n\nMesaj pentru client (copiază și trimite):\n<i>${esc(draft)}</i>`;
}
return [{ json: { chatId: p.chatId, text, claimId: p.claimId, ref: c.public_ref, missing: items.map((m) => m.label) } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Why Code: răspunsul agentului pentru Telegram: numele brokerilor puse în locul marcajelor [broker:<id>] (numele nu trec
// prin LLM), HTML escapat, **bold** → <b>, limită de lungime; la eroare, mesaj clar.
const p = $('Parse update').first().json;
const r = $('Broker agent').first().json ?? {};
let brokers = [];
try { brokers = JSON.parse($input.first().json.data || '[]'); } catch { brokers = []; }
const names = new Map((Array.isArray(brokers) ? brokers : []).map((b) => [String(b.id).toLowerCase(), String(b.name ?? '').trim()]));
const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
const nameOf = (id) => names.get(String(id).toLowerCase()) || 'un broker';
let answer = typeof r.output === 'string' ? r.output.trim() : '';
answer = answer
  .replace(new RegExp('\\[\\s*broker\\s*:\\s*(' + UUID + ')\\s*\\]', 'gi'), (_m, id) => nameOf(id))
  // dacă agentul a scris doar id-ul, fără marcaj
  .replace(new RegExp('(?<![0-9a-f-])(' + UUID + ')(?![0-9a-f-])', 'gi'), (m, id) => (names.has(id.toLowerCase()) ? nameOf(id) : m));
const text = answer
  ? esc(answer).replace(/\*\*([^*\n]+?)\*\*/g, '<b>$1</b>')
  : '⚠️ Asistentul nu răspunde acum. Încearcă mai târziu sau folosește dashboardul.';
return [{ json: { chatId: p.chatId, text: text.slice(0, 3900) } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Why Code: textul de ajutor, plus un indiciu opțional (comandă fără argument).
const p = $('Parse update').first().json;
const lines = [
  p.hint ? esc(p.hint) + '\n' : null,
  '<b>BrokerPilot Desk</b> (asistent AI)',
  'Scrie liber, de exemplu: „ce dosare am deschise?”, „ce lipsește la BP-2611-00017?”, „care e termenul de notificare la Allianz?”.',
  'Scurtături: /dosare, /intreaba &lt;întrebare&gt;.',
  'Butoanele din mesajele despre dosare: „Preiau” și „Cere info lipsă”.',
].filter(Boolean);
return [{ json: { chatId: p.chatId, text: lines.join('\n') } }];

// Why Code: numele clienților agenției din întrebare devin <NUME> înainte de agent (ca knownNames în lib/kb/copilot.ts):
// „polița lui Popescu” nu pleacă la LLM cu numele. Potrivire pe cuvânt întreg, fără diferență de majuscule sau diacritice.
const p = $('Parse update').first().json;
let rows = [];
try { rows = JSON.parse($input.first().json.data || '[]'); } catch { rows = []; }
const parts = new Set();
for (const r of Array.isArray(rows) ? rows : []) {
  for (const w of String(r?.full_name ?? '').replace(/\s*\(fictiv\)\s*$/i, '').split(/[\s-]+/)) if (w.length >= 3) parts.add(w);
}
const CLS = { a: '[aăâ]', ă: '[aăâ]', â: '[aăâ]', i: '[iî]', î: '[iî]', s: '[sșş]', ș: '[sșş]', ş: '[sșş]', t: '[tțţ]', ț: '[tțţ]', ţ: '[tțţ]' };
const esc = (c) => c.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
let question = p.question;
// mai lungi întâi, ca „Popescu” să nu fie tăiat de „Pop”
for (const w of [...parts].sort((a, b) => b.length - a.length)) {
  const body = [...w.toLowerCase()].map((c) => CLS[c] ?? esc(c)).join('');
  question = question.replace(new RegExp('(?<![\\p{L}\\d])' + body + '(?![\\p{L}\\d])', 'giu'), '<NUME>');
}
return [{ json: { ...p, question, namesRedacted: question !== p.question, startedAt: Date.now() } }];
